#include <iostream>
#include <algorithm>

using namespace std;

long long HigherDividend(long long x, long long divider) {
    if (x % divider == 0) return x;
    if (x < divider) return 0;
    return (x / divider) * divider;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long cnt1, cnt2, x, y;
    cin >> cnt1 >> cnt2 >> x >> y;

    long long count = 0;
    long long barrier = cnt1 + cnt2;
    long long xy = x * y;

    while (count != cnt1 + cnt2) {
        long long bad = HigherDividend(barrier, xy) / xy;
        long long xCountCommon = HigherDividend(barrier, y) / y - bad;
        long long yCountCommon = HigherDividend(barrier, x) / x - bad;
        long long xCount = min(xCountCommon, cnt1);
        long long yCount = min(yCountCommon, cnt2);
        if (xCount < xCountCommon) bad += xCountCommon - xCount;
        if (yCount < yCountCommon) bad += yCountCommon - yCount;
        long long good = barrier - bad - xCount - yCount;
        count = good + xCount + yCount;
        barrier += cnt1 + cnt2 - count;
    }

    cout << barrier << endl;
    return 0;
}

